DOUBLE_EXTENSION_LIST = ('.tar.gz', '.tar.bz2', '.tar.z', '.tar.lzma', '.tar.xz')


def get_timestamp_for_filesystem():
    """
    Gets current time (local) and returs formated string
    :return: YYYY.MM.DD_HH.SS as a string
    """
    year, month, mday, hour, mn, sec, wday, yday, isdst = time.localtime()
    timestamp = '{yyyy}.{mm:02}.{dd:02}_{hh:02}.{mi:02}.{ss:02}'.format(
        yyyy=year, mm=month, dd=mday, hh=hour, mi=mn, ss=sec
    )
    return timestamp


def get_filename_without_timestamp_suffix(input_filename):
    """
    Removes timestamp pattern from given file (even when '_YYYY.MM.DD_HH.MM.SS' is not at the end)
    :param input_filename: file with timestamp
    :return: filename without timestamp
    """
    timestamp_pattern = r'_\d{4}.\d{2}.\d{2}_\d{2}.\d{2}.\d{2}'
    filename_without_suffix = re.sub(timestamp_pattern, '', input_filename)
    return filename_without_suffix


def get_filename_without_extension_from_filepath(file_path):
    """
    Gets filename without extension for given file path.
    Normally it strip out everything after last dot.
    Two-parts extensions with '.tar.' are exceptions - in this case it removes .tar.xx extension.
    :param file_path: path to the file, i.e. '/home//ute/myfile.txt'
    :return: filename without extension
    """
    file_name = os.path.basename(file_path)
    name, first_ext = os.path.splitext(file_name)
    first_ext = first_ext.lower()
    if [first_ext in x for x in DOUBLE_EXTENSION_LIST]:
        stripped_name, second_ext = os.path.splitext(name)
        second_ext = second_ext.lower()
        double_extension = second_ext + first_ext
        if double_extension in DOUBLE_EXTENSION_LIST:
            return stripped_name

    return name


def get_file_extension_from_filepath(file_path):
    """
    Returns file extension (without leading dot) as a string.
    Ready for double extensions exception.
    :param file_path: path to the file, i.e. '/home/ute/myfile.txt'
    :return: extension of the given file as a string
    """
    file_name = os.path.basename(file_path)
    file_name = file_name.lower()
    name, ext = os.path.splitext(file_name)
    if ext != '':
        for x in DOUBLE_EXTENSION_LIST:
            if file_name.endswith(x):
                name, first_ext = os.path.splitext(name)
                ext = first_ext + ext
                return ext.lstrip('.')
    extension = ext.lstrip('.')
    return extension


def split_path_to_parent_dirpath_name_and_extension(file_path):
    """
    Splits given file path into file location (parent path), file name wihout extension (bare name) and extension
    :param file_path: filepath, i.e. '/home/ute/myfile.txt'
    :return: parent path, bare name, extension as strings
    """
    parent_path, file_name = os.path.split(file_path)
    bare_name = get_filename_without_extension_from_filepath(file_path)
    extension = get_file_extension_from_filepath(file_path)
    return parent_path, bare_name, extension


def join_path_with_timestamp_suffix(base, *parts):
    """
    Joins path and path's parts given as args argument into path and filename with timestamp suffix
    :param base: path to the file
    :param parts: split parts of the path
    :return: joined path and filename with timestamp suffix
    """
    joined_path = os.path.join(base, *parts)
    parent_dirpath, base_name, extension = split_path_to_parent_dirpath_name_and_extension(joined_path)
    base_name = get_filename_without_timestamp_suffix(base_name)
    time_stamp = get_timestamp_for_filesystem()
    final_path = _get_final_path(parent_dirpath, base_name, time_stamp, extension)
    return final_path


def _get_final_path(parent_dirpath, base_name, time_stamp, extension):
    if extension:
        final_path = os.path.join(parent_dirpath, base_name + '_' + time_stamp + '.' + extension)
    else:
        final_path = os.path.join(parent_dirpath, base_name + '_' + time_stamp)
    return final_path


def create_timestamped_directory(parent_dirpath, dirname):
    """
    Creates directory with timestamp. Timestamp follows directory name.
    :param parent_dirpath: path where new directory will be created
    :param dirname: new directory name
    :return: creates directory and return full path of the new directory as a string
    """
    timestamped_directory = join_path_with_timestamp_suffix(parent_dirpath, dirname)
    os.mkdir(timestamped_directory)
    return timestamped_directory


def compress_files(input_dirpath, output_dirpath, output_filename_prefix, file_filter='*',
                   compresslevel=5):
    """
    Compress files from given path to given path and removes compressed files
    :param input_dirpath: path to the files that will be compressed
    :param output_dirpath: path for output archive
    :param output_filename_prefix: archive filename
    :return: Nothing
    """
    files_to_compress = _get_filtered_files(input_dirpath, file_filter)
    tar_archive_path = os.path.join(output_dirpath, output_filename_prefix + '.tar.gz')
    _compress_list_of_files(files_to_compress, tar_archive_path, compresslevel=compresslevel)
    _remove_files_from_path(input_dirpath, files_to_compress)


def _compress_list_of_files(files_to_compress, tar_archive, compresslevel=5):
    with tarfile.open(tar_archive, 'w:gz', compresslevel=int(compresslevel)) as tar:
        for element in files_to_compress:
            tar.add(element, arcname=os.path.basename(element))


def _get_filtered_files(input_dirpath, file_filter):
    filtered_filelist = glob.glob(os.path.join(input_dirpath, file_filter))
    return filtered_filelist


def _remove_files_from_path(dir_path, file_list):
    for element in file_list:
        path_to_check = os.path.join(dir_path, element)
        if os.path.isdir(path_to_check):
            shutil.rmtree(path_to_check)
        else:
            os.remove(path_to_check)


def _safe_copy_file(source, destination):
    """
    Copies the file from source location to destination
    :param source: source file, including path
    :param destination: destination path and optionally file name
    :return: nothing
    """
    output = ''
    if '@' in source:
        try:
            output = check_output('scp {} {}'.format(source, destination.replace(' ', '_')), shell=True)
        except Exception as e:
            logger.info('scp failed while copying files: {}'.format(output))
            raise e
    else:
        temp = tempfile.mkdtemp()
        file_path, file_name = os.path.split(source)
        file_temp_copy = os.path.join(temp, file_name)
        shutil.copy(source, file_temp_copy)
        shutil.copy(file_temp_copy, destination)


def _safe_move_file(source, destination):
    """
    Moves the file from source location to destination
    :param source: source file, including path
    :param destination: destination path and optionally file name
    :return: nothing
    """
    temp = tempfile.mkdtemp()
    file_path, file_name = os.path.split(source)
    file_temp_copy = os.path.join(temp, file_name)
    shutil.move(source, file_temp_copy)
    dir_destination = os.path.dirname(destination)
    if not os.path.exists(dir_destination):
        os.makedirs(dir_destination)
    shutil.move(file_temp_copy, destination)


def safe_copy_files(sources, destination):
    """
    Safely copy list of files or a file
    :param destination: destination path optionally including file name
    :param sources: source file(s)
    :return: nothing
    """
    if isinstance(sources, str):
        sources = force_list(sources)

    if not isinstance(sources, list):
        sources = [sources]
    for source in sources:
        _safe_copy_file(source, destination)


def safe_move_files(sources, destination):
    """
    Safely moves list of files or a file
    :param destination: destination path optionally including file name
    :param sources: source file(s)
    :return: nothing
    """
    if isinstance(sources, str):
        sources = force_list(sources)

    if not isinstance(sources, list):
        sources = [sources]
    for source in sources:
        for f in glob.glob(source):
            _safe_move_file(f, destination)


def move_files_and_add_timestamp_suffixes(destination, sources):
    """
    Move files from source to destination and adds timestamp suffix to the file name
    :param destination: target path for moved files
    :param sources: file(s) to be moved and renamed
    :return: nothing
    """

    for source in sources:
        destination_filepath = _prepare_file_for_copy(destination, source)
        _safe_move_file(source, destination_filepath)


def copy_files_and_add_timestamp_suffixes(destination, sources):
    """
    Copy files from source to destination and adds timestamp suffix to the file name
    :param destination: target path for copied files
    :param sources: file(s) to be copied and renamed
    :return: nothing
    """
    if isinstance(sources, str):
        sources = force_list(sources)

    if not isinstance(sources, list):
        sources = [sources]
    for source in sources:
        destination_filepath = _prepare_file_for_copy(destination, source)
        _safe_copy_file(source, destination_filepath)


def _prepare_file_for_copy(destination, source):
    source_bare_filename = get_filename_without_extension_from_filepath(source)
    source_file_extension = get_file_extension_from_filepath(source)
    destination_filepath = join_path_with_timestamp_suffix(
        destination, source_bare_filename + '.' + source_file_extension
    )
    return destination_filepath


def duplicate_file_with_added_suffix(input_filepath, suffix):
    """
    Duplicates given file and adds given suffix to the file name
    :param input_filepath: file name including path
    :param suffix: string to be added to file name
    :return: nothing
    """
    parent_dirpath, bare_name, extension = split_path_to_parent_dirpath_name_and_extension(input_filepath)
    destination = os.path.join(parent_dirpath, bare_name + suffix + '.' + extension)
    _safe_copy_file(input_filepath, destination)
    return destination


def create_log_folder_for_current_test_case():
    """
    Creates test log folder from TEST_NAME and OUTPUT_DIR Robot variables
    :return: created directory /output_dir/test_name
    """
    fixed_test_name = _fix_robot_name(get_robot_test_name())
    path_to_tc_logs = os.path.join(get_robot_output_dir(), fixed_test_name)
    BuiltIn().set_test_variable('${PATH_TO_TC_LOGS}', path_to_tc_logs)
    BuiltIn().set_test_variable('${FIXED_TEST_NAME}', fixed_test_name)
    os.mkdir(path_to_tc_logs)


def get_config_directory_path():
    """
    Sets config directory as a Robot variable ${config_dirpathl}
    :return: config dirpath as a string
    """
    testsuite_split_path = os.path.split(get_robot_suite_source())
    config_dirpath = testsuite_split_path[0] + os.path.sep + 'config'
    BuiltIn().set_suite_variable('${config_dirpath}', config_dirpath)
    return config_dirpath


def clean_environment_from_old_logs():
    """
    Cleans test environment. Removes *log* files from /opt/iphy/latest and entire /tmp content
    :return: nothing
    """
    call('cd /opt/iphy/latest; sudo rm -rf *log*', shell=True)
    call('cd /tmp; sudo rm -rf *', shell=True)
    output_dir = get_robot_output_dir()

    files_to_delete = _get_filtered_files(output_dir, '*log*')
    _remove_files_from_path(output_dir, files_to_delete)


def compress_test_logs(compresslevel=5):
    """
    Compress test logs
    :return:
    """
    current_timestamp = get_timestamp_for_filesystem()
    fixed_suite_name = _fix_robot_name(get_robot_suite_name())
    suffix = 'testlogs.tar.gz'
    output_dir = get_robot_output_dir()
    log_filepath = os.path.join(output_dir, fixed_suite_name + '_' + current_timestamp + '_' + suffix)
    files_to_compress = _get_filtered_files(output_dir, '*')
    modified_file_to_compress_list = _remove_robot_specic_logs_from_file_list(files_to_compress)
    _compress_list_of_files(modified_file_to_compress_list, log_filepath, compresslevel=compresslevel)
    _remove_files_from_path(output_dir, modified_file_to_compress_list)


def change_ext_from_xml_to_json(input_scfc_filename):
    return input_scfc_filename.replace(".xml", ".json")


def _fix_robot_name(robot_name):
    return robot_name.replace(' ', '_')


def _remove_robot_specic_logs_from_file_list(file_list):
    final_list = []
    for f in file_list:
        path, file_name = os.path.split(f)
        if not (
            file_name in ['output.xml', 'log.html', 'report.html']
            or 'egate_console.log' in file_name
            or 'testlogs.tar.gz' in file_name
        ):
            final_list.append(os.path.join(path, file_name))
    return final_list


def move_files_from_testpath_and_add_timestamp_suffixes(destination):
    """
    Move files from testpath (output_dir/suite_name/test_name) to given destiantion path.
    :param destination: where to move files
    :return: testpath dir content is moved to destination, timestamps are added
    """
    testpath_dirpath = get_test_path()
    testpath_filepaths = _get_filtered_files(testpath_dirpath, '*')
    move_files_and_add_timestamp_suffixes(destination, testpath_filepaths)
    shutil.rmtree(testpath_dirpath)


def unpack_file_from_tar_xz_archive(filepath, command):
    """
    Unpacks file from XZ archive, deleting exisiting archive file
    :param filepath: path to archive including filename
    :return: unpack file path
    """

    os.chmod(filepath, 0o755)
    target_file = get_filename_without_extension_from_filepath(filepath)
    target_path = os.path.split(filepath)[0]
    target_filepath = os.path.join(target_path, target_file)
    call('{} {}'.format(command, filepath), shell=True)
    return target_filepath


def set_log_directory(log_dir, keep_underscores=True):
    """
    Creates log directory if it was specified, otherwise sets unified test path as log directory.
    :param string  log_dir:  Specified path to directory where log files should be stored.
    :return: New path to directory where logs file should be stored.
    """
    if log_dir is None:
        log_dir = get_test_path(keep_underscores)
    if not os.path.exists(log_dir):
        os.makedirs(log_dir)
    return log_dir


def get_test_hierarchy():
    """Return list containing test hierarchy structure of currently executed test.

    :return: Current test hierarchy based on test phase.
    :rtype: list
    """
    current_test_hierarchy = get_robot_suite_name().split('.')
    if get_robot_test_name() is not None:
        current_test_hierarchy.append(get_robot_test_name())

    current_test_hierarchy = [convert_string(test_hier_item) for test_hier_item in current_test_hierarchy]
    return current_test_hierarchy


def get_test_path(keep_underscores=False):
    """Return log folder path for current test built from test hierarchy structure of currently executed test case.

    :param keep_underscores: allows to generate the path without removing underscores

    :return: Unified test path calculated from ${OUTPUT} variable available during test execution.
    :rtype: string
    """
    current_test_hierarchy = get_test_hierarchy()
    current_test_hierarchy_path = os.path.join(*current_test_hierarchy)

    if keep_underscores:
        current_test_hierarchy_path = current_test_hierarchy_path.replace(' ', '_')

    current_test_log_folder_path = os.path.join(get_robot_output_dir(), current_test_hierarchy_path)
    current_test_log_folder_path = os.path.normpath(current_test_log_folder_path)

    return current_test_log_folder_path


def convert_string(value):
    """Normalizes string, removes characters that are not allowed in file names.
    """
    return _convert_string(value)


def _convert_string(value):
    """Normalizes string, removes characters that are not allowed in file names.
    """
    value = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore')
    valid_chars = "-_.() {}{}".format(string.ascii_letters, string.digits)
    return ''.join([_to_string(c) for c in value if _to_string(c) in valid_chars])


def _to_string(char):
    return str(chr(char)) if isinstance(char, int) else char


def get_tempdir():
    """Return OS-specific temp directory.
        """
    return tempfile.gettempdir()


def remove_files(*list_of_files):
    """Removes files given as list.
        """
    new_list_of_files = []
    for tuple_element in list_of_files:
        if isinstance(tuple_element, list):
            for file_list in tuple_element:
                new_list_of_files.append(file_list)
        else:
            new_list_of_files.append(tuple_element)

    if len(new_list_of_files) == 0:
        raise RuntimeError('remove_files: list_of_files does not have any file to remove')
    dir_of_files = os.path.dirname(new_list_of_files[0])
    _remove_files_from_path(dir_of_files, new_list_of_files)


def get_authorization_bearer_token():
    """
    Obtains and returns authorization token for artifactory.
    :return Authorization token for artifactory.
    """
    with open("/etc/token/ca_ute_artifactory_readonly") as cert_file:
        return {"Authorization": "Bearer " + cert_file.read().strip()}


def download_bsr_package(file_url, download_filepath, auth_token, chunk_size=128):
    """
    Downloads BSR package from the provided url and saves it to filepath

    :param file_url: str
    :param download_filepath: str
    :param auth_token: dict[str, str]
    :param chunk_size: int, default 128
    """
    r = requests.get(file_url, headers=auth_token, stream=True)
    if r.status_code == 200:
        logger.debug(f"File exists at {file_url}. Starting download to path {download_filepath}")
        with open(download_filepath, 'wb') as fd:
            for chunk in r.iter_content(chunk_size=chunk_size):
                fd.write(chunk)
    else:
        logger.debug(f"File not found at {file_url}")
        logger.debug(r.status_code)
        raise Exception(f"File not found at URL: {file_url}")
